from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to ''. """
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute common-prefix length using binary-search slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute exact ideal character-Trie reuse from sorted adjacent strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each row using its supplied source-column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells) -> List[int]:
        """Rank columns by length-weighted repeated-value mass."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1

            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _canonical_orders(self, cells) -> List[List[int]]:
        """Sort each row's fields lexically, using repetition and index tie-breaks."""
        n, m = cells.shape

        repetition = []
        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
            repetition.append(
                sum(count * (count - 1) for count in counts.values())
            )

        orders = []
        wide = m > 32

        for row in range(n):
            indices = list(range(m))

            if not wide:
                indices.sort(
                    key=lambda column: (
                        cells[row, column],
                        -repetition[column],
                        column,
                    )
                )
                orders.append(indices)
                continue

            # Bucket first on a short prefix to avoid excessive comparisons
            # for wide tables, then fully resolve only equal-prefix buckets.
            buckets = {}
            for column in indices:
                prefix = cells[row, column][:32]
                buckets.setdefault(prefix, []).append(column)

            ordered = []
            for prefix in sorted(buckets):
                bucket = buckets[prefix]
                bucket.sort(
                    key=lambda column: (
                        cells[row, column],
                        -repetition[column],
                        column,
                    )
                )
                ordered.extend(bucket)
            orders.append(ordered)

        return orders

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Choose a repeated leading field and rank suffixes within each value group."""
        n, m = cells.shape
        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        lead_scores = []
        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1

            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            lead_scores.append((score, column))

        lead_scores.sort(key=lambda item: (-item[0], item[1]))
        lead = lead_scores[0][1]

        groups = {}
        for row in range(n):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [column for column in range(m) if column != lead]
        result = [None] * n

        for rows in groups.values():
            ranked = []
            for column in remaining:
                counts = {}
                for row in rows:
                    value = cells[row, column]
                    counts[value] = counts.get(value, 0) + 1

                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                ranked.append((score, column))

            ranked.sort(key=lambda item: (-item[0], item[1]))
            order = [lead] + [column for _, column in ranked]

            for row in rows:
                result[row] = order[:]

        return result

    def _candidate(self, cells, orders):
        """Serialize, score, and canonically sort one complete candidate."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row)
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate global, row-canonical, and conditional lossless permutations."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_order = self._global_order(cells)
        canonical_orders = self._canonical_orders(cells)
        conditional_orders = self._conditional_orders(cells)

        candidates = [
            [global_order[:] for _ in range(n)],
            canonical_orders,
            conditional_orders,
        ]

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column] for column in source_order
            ]
            column_orders.append([
                df.columns[column] for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders
